    for (const gpu of usage)
        gpu.used = round(gpu.used);
    return { gpus: usage, total,
        capacity: round(usage.reduce((sum, gpu) => sum + gpu.capacity, 0)),
        excess: round(usage.reduce((sum, gpu) => sum + Math.max(0, gpu.used - gpu.capacity), 0)) };
